<?php
namespace qqworld_collector\module; use qqworld_collector\lib; class check_duplicated_title extends lib { var $options; var $log_id = 'collection-project'; public function __construct() { add_filter( 'qqworld-collector-script-translation-array', array($this, 'admin_localize_script') ); add_action( 'wp_ajax_qqworld-collector-check-duplicated-title', array($this, 'ajax_check_duplicated_title') ); add_action( 'wp_ajax_nopriv_qqworld-collector-check-duplicated-title', array($this, 'ajax_check_duplicated_title') ); } public function admin_localize_script($translation_array) { $translation_array['check_duplicated_title'] = $this->options->qc_detectd_duplicate_titles ? true : false; return $translation_array; } public function check_duplicated_title($ID, $title, $post_metas, $post_statuses = array('publish', 'pending', 'draft')) { global $wpdb; $post_statuses = "'".implode("', '", $post_statuses)."'"; if ($this->options->qc_detectd_duplicate_post_meta) { do_action('qqworld-collector-log', $this->log_id, 'Check Duplicated:', '$post_metas: '.print_r($post_metas, true)); $meta_value = isset($post_metas[$this->options->qc_detectd_duplicate_post_meta]) ? $post_metas[$this->options->qc_detectd_duplicate_post_meta] : ''; if ($meta_value) $sql = "SELECT a.* FROM `{$wpdb->posts}` a INNER JOIN `{$wpdb->postmeta}` b ON a.`post_title`='{$title}' AND a.`post_status` IN ({$post_statuses}) AND a.`ID`<>{$ID} AND a.`ID` = b.`post_id` AND b.`meta_key` = '{$this->options->qc_detectd_duplicate_post_meta}' AND b.`meta_value` = '{$meta_value}'"; else $sql = false; } else { $sql = "SELECT * FROM `{$wpdb->posts}` WHERE `post_title`='{$title}' AND `post_status` IN ({$post_statuses}) AND `ID`<>{$ID}"; } if ($sql) { $posts = $wpdb->get_col($sql); do_action('qqworld-collector-log', $this->log_id, 'Check Duplicated:', '$sql: '.$sql."\nAnd found number of posts: ".count($posts)); } else { $posts = array(); } return $posts; } public function ajax_check_duplicated_title() { $title = isset($_POST['post_title']) ? $_POST['post_title'] : ''; $ID = isset($_POST['post_ID']) ? $_POST['post_ID'] : ''; $resules = array( 'duplicated_titles' => 0 ); if ($title && $ID) { $post_metas = array(); if ($this->options->qc_detectd_duplicate_post_meta) { if (isset($_POST['meta'])) foreach ($_POST['meta'] as $meta) { $post_metas[$meta['key']] = $meta['value']; } } $posts = $this->check_duplicated_title($ID, $title, $post_metas); $resules['posts'] = $posts; if (count($posts)) { $resules['duplicated_titles'] = 1; $resules['msg'] = sprintf(_n('Found %d post has same title.', 'Found %d posts have same title.', count($posts), $this->text_domain), number_format_i18n(count($posts))); $resules['msg'] .= '<ul>'; foreach ($posts as $post) $resules['msg'] .= '<li><a href="'.admin_url('post.php?post='.$post.'&action=edit').'" target="_blank">'.$title.'</a></li>'; $resules['msg'] .= '</ul>'; $resules['msg'] .= '<div align="right"><em>' . sprintf(__('You can turn it off <a href="%s" target="_blank">here</a>.', $this->text_domain), admin_url('admin.php?page=qqworld-collector-settings#download')) . '</em></div>'; } } echo json_encode($resules, JSON_INVALID_UTF8_IGNORE); exit; } } ?>